/**
 * dialog-relay.ts — relay auth token data from the URL fragment to the parent.
 *
 */

(function (): void {
  Office.onReady(function () {
    var fragment = window.location.hash.substring(1); // strip leading '#'
    if (!fragment) {
      Office.context.ui.messageParent(JSON.stringify({ error: "No data received from auth dialog." }));
      return;
    }

    try {
      var decoded = decodeURIComponent(fragment);
      var data = JSON.parse(decoded);
      Office.context.ui.messageParent(JSON.stringify(data));
    } catch (e) {
      Office.context.ui.messageParent(
        JSON.stringify({ error: "Failed to parse auth response: " + (e as Error).message })
      );
    }
  });
})();
